begin;
set local lock_timeout='5s';set local statement_timeout='45s';
select set_config('request.jwt.claims','{}',true);
do $$ declare u uuid; k text; e uuid; begin
 foreach k in array array['customer','other','editor','reviewer','operator','sgoperator'] loop
  u:=gen_random_uuid();insert into auth.users(id,email,email_confirmed_at)values(u,'extension-qa-'||u||'@example.invalid',now());perform set_config('extension.'||k,u::text,true);
 end loop;
 insert into public.staff_roles(user_id,market,role)values(current_setting('extension.editor')::uuid,'PH','editor'),(current_setting('extension.reviewer')::uuid,'PH','compliance'),(current_setting('extension.operator')::uuid,'PH','operations'),(current_setting('extension.sgoperator')::uuid,'SG','operations');
 insert into public.content_entries(slug,kind,title,status,market,starts_at)values('qa-event-'||gen_random_uuid(),'event','QA capacity event','published','PH',now()+interval '2 days')returning id into e;perform set_config('extension.event',e::text,true);
 insert into public.content_entries(slug,kind,title,body,status,market,locale,approved_at) values('assistant-qa-'||gen_random_uuid(),'page','QA approved source','QA approved packaging information.','published','PH','en',now());
 insert into public.content_entries(slug,kind,title,body,status,market,locale) values('assistant-draft-'||gen_random_uuid(),'page','QA secret draft','Must never reach assistant.','draft','PH','en'),('assistant-sg-'||gen_random_uuid(),'page','QA Singapore','Must not reach PH assistant.','published','SG','en');
 insert into public.profiles(id,full_name,phone)values(current_setting('extension.customer')::uuid,'QA Own Name','000000000'),(current_setting('extension.other')::uuid,'Other private customer','111111111');
end $$;
set local role authenticated;
do $$ declare e uuid:=current_setting('extension.event')::uuid; r uuid; a uuid; s uuid; result jsonb; begin
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('extension.reviewer'),'role','authenticated','aal','aal2')::text,true);
 perform public.save_event_admission(e,1,0,'QA-CAPACITY');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('extension.customer'),'role','authenticated','aal','aal1')::text,true);
 insert into public.event_registrations(user_id,event_id,checked_in_at,checked_in_by,status,revision)values(current_setting('extension.customer')::uuid,e,now(),current_setting('extension.customer')::uuid,'cancelled',100)returning id into r;
 perform set_config('extension.registration',r::text,true);
 result:=public.event_attendance(e,false);
 if result->'attendees'->0->>'checkedInAt' is not null or result->'attendees'->0->>'status'<>'registered' or (result->'attendees'->0->>'revision')::int<>0 then raise exception 'FAIL: forged checkin';end if;
 begin perform public.event_attendance(e,true);raise exception 'FAIL: customer attendee list';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('extension.other'),'role','authenticated','aal','aal1')::text,true);
 begin insert into public.event_registrations(user_id,event_id)values(current_setting('extension.other')::uuid,e);raise exception 'FAIL: capacity exceeded';exception when check_violation then null;end;
 begin perform public.change_event_attendance(r,0,false);raise exception 'FAIL: cancel other attendee';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('extension.customer'),'role','authenticated','aal','aal1')::text,true);
 perform public.change_event_attendance(r,0,false);
 result:=public.export_my_data();
 if result->>'subjectId'<>current_setting('extension.customer') or result->'profile'->>'full_name'<>'QA Own Name' or result::text like '%Other private customer%' then raise exception 'FAIL: privacy export isolation';end if;
 result:=public.assistant_sources('PH','en');
 if not exists(select 1 from jsonb_array_elements(result) x where x->>'title'='QA approved source') or exists(select 1 from jsonb_array_elements(result) x where x->>'title' in ('QA secret draft','QA Singapore')) then raise exception 'FAIL: approved assistant corpus';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('extension.other'),'role','authenticated','aal','aal1')::text,true);
 insert into public.event_registrations(user_id,event_id)values(current_setting('extension.other')::uuid,e)returning id into r;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('extension.sgoperator'),'role','authenticated','aal','aal2')::text,true);
 begin perform public.change_event_attendance(r,0,true);raise exception 'FAIL: cross market checkin';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('extension.operator'),'role','authenticated','aal','aal2')::text,true);
 perform public.change_event_attendance(r,0,true);
 begin perform public.change_event_attendance(r,0,true);raise exception 'FAIL: stale checkin';exception when serialization_failure then null;end;
 perform public.change_event_attendance(r,1,true);
 begin perform public.change_event_attendance(r,1,false);raise exception 'FAIL: cancel checked in attendee';exception when invalid_parameter_value then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('extension.editor'),'role','authenticated','aal','aal2')::text,true);
 a:=public.save_library_version(null,0,'PH',jsonb_build_object('title','QA documentary','locale','en','mediaType','video','url','https://vimeo.com/123','transcript','Accessible QA transcript','disclaimer','Approved QA disclaimer.'));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('extension.reviewer'),'role','authenticated','aal','aal2')::text,true);
 perform public.review_library_version(a,1,'QA-FILM-RIGHTS',false);
 insert into public.content_entries(slug,kind,title,status,market,story_asset_id) values('qa-story-'||gen_random_uuid(),'story','QA documentary story','published','PH',a) returning id into s;
 perform set_config('extension.story',s::text,true);
 if not private.story_media_available(a,'PH') or private.story_media_available(a,'SG') then raise exception 'FAIL: story market restriction';end if;
 perform public.review_library_version(a,1,'QA-FILM-WITHDRAW',true);
 if private.story_media_available(a,'PH') then raise exception 'FAIL: withdrawn story media';end if;
end $$;
reset role;
select set_config('request.jwt.claims','{}',true);
set local role anon;
do $$ begin
 if exists(select 1 from public.content_entries where id=current_setting('extension.story')::uuid) then raise exception 'FAIL: story visible after media withdrawal';end if;
 if has_function_privilege('anon','public.export_my_data()','execute') then raise exception 'FAIL: anonymous personal export';end if;
 if has_function_privilege('service_role','public.export_my_data()','execute') then raise exception 'FAIL: service export without owner context';end if;
end $$;
rollback;
